-- ---------------------------------------------------------------------------
-- B. Opening a lobby draws the prize (4720 plus accessory and packs)
-- ---------------------------------------------------------------------------
create or replace function public.battle_open(p_now timestamptz)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg    jsonb := public.battles_cfg();
  w      jsonb := cfg #> '{prizes,weights}';
  tw     jsonb := cfg #> '{prizes,accessoryTiers}';
  v_tot  double precision;
  v_roll double precision;
  v_kind text := 'xp';
  v_art  uuid;
  v_id   bigint;
  v_prize jsonb;
  v_tier text;
  v_packs jsonb;
  k      text;
begin
  perform pg_advisory_xact_lock(7311160);
  if exists (select 1 from public.battles b where b.status in ('open', 'running')) then
    return null;
  end if;
  select sum(value::double precision) into v_tot from jsonb_each_text(coalesce(w, '{}'::jsonb));
  v_roll := random() * coalesce(v_tot, 0);
  for k in select key from jsonb_each_text(coalesce(w, '{}'::jsonb)) order by key loop
    v_roll := v_roll - (w ->> k)::double precision;
    if v_roll < 0 then v_kind := k; exit; end if;
  end loop;
  if v_kind = 'nft' then
    v_art := public.battle_free_artwork();
    if v_art is null then v_kind := 'money'; end if;
  elsif v_kind = 'skin' and coalesce(jsonb_array_length(cfg -> 'accessories'), 0) = 0 then
    v_kind := 'xp';
  elsif v_kind = 'accessory' then
    -- the tier: weighted, keys in sorted order (pickWeighted)
    select sum(value::double precision) into v_tot from jsonb_each_text(coalesce(tw, '{}'::jsonb)) where value::double precision > 0;
    v_roll := random() * coalesce(v_tot, 0);
    for k in select key from jsonb_each_text(coalesce(tw, '{}'::jsonb)) where value::double precision > 0 order by key loop
      v_tier := k;
      v_roll := v_roll - (tw ->> k)::double precision;
      exit when v_roll < 0;
    end loop;
    if v_tier is null then v_kind := 'money'; end if;
  elsif v_kind = 'packs' then
    v_packs := public.battle_pick_packs(coalesce((cfg #>> '{prizes,packsCapCents}')::bigint, 0),
                                        coalesce((cfg #>> '{prizes,packsMax}')::integer, 1),
                                        random(), random(), random(), random());
    if jsonb_array_length(v_packs) = 0 then v_kind := 'money'; end if;
  end if;
  v_prize := jsonb_build_object('kind', v_kind);
  if v_kind = 'accessory' then v_prize := v_prize || jsonb_build_object('tier', v_tier); end if;
  if v_kind = 'packs' then v_prize := v_prize || jsonb_build_object('packs', v_packs); end if;
  insert into public.battles (status, seed, prize, artwork_id, opened_at)
  values ('open', floor(random() * 4294967296)::bigint, v_prize, v_art, p_now)
  returning id into v_id;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. What the prize is worth, its label, the payout (4720 plus accessory and packs)
-- ---------------------------------------------------------------------------
create or replace function public.battle_prize_json(p_battle public.battles, p_players integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg  jsonb := public.battles_cfg() -> 'prizes';
  v_n  integer := greatest(coalesce(p_players, 0), coalesce((public.battles_cfg() #>> '{lobby,minPlayers}')::integer, 3));
  v_mult double precision := coalesce((public.config_jsonb('progression') ->> 'xpMultiplier')::double precision, 1);
  a    public.artworks;
begin
  if p_battle.result ? 'prize' then
    return p_battle.result -> 'prize';
  end if;
  case p_battle.prize ->> 'kind'
    when 'xp' then
      return jsonb_build_object('kind', 'xp', 'xp',
        round(((cfg ->> 'xpBase')::integer + (cfg ->> 'xpPerPlayer')::integer * v_n) * v_mult)::integer);
    when 'money' then
      return jsonb_build_object('kind', 'money', 'cents',
        (cfg ->> 'moneyBaseCents')::bigint + (cfg ->> 'moneyPerPlayerCents')::bigint * v_n);
    when 'skin' then
      return jsonb_build_object('kind', 'skin', 'accessories',
        coalesce((select jsonb_agg(x ->> 'key') from jsonb_array_elements(public.battles_cfg() -> 'accessories') x), '[]'::jsonb));
    when 'accessory' then
      return jsonb_build_object('kind', 'accessory', 'tier', coalesce(p_battle.prize ->> 'tier', 'rare'));
    when 'packs' then
      return public.battle_packs_json(p_battle.prize -> 'packs');
    when 'nft' then
      select * into a from public.artworks x where x.id = p_battle.artwork_id;
      if a.id is null then
        return jsonb_build_object('kind', 'money', 'cents',
          (cfg ->> 'moneyBaseCents')::bigint + (cfg ->> 'moneyPerPlayerCents')::bigint * v_n);
      end if;
      return jsonb_build_object('kind', 'nft', 'artwork',
        jsonb_build_object('id', a.id, 'title', a.title, 'serial', a.serial, 'rarity', a.rarity, 'pixels', a.pixels));
    else
      return jsonb_build_object('kind', 'xp', 'xp', 0);
  end case;
end;
$$;

create or replace function public.battle_prize_label(p_prize jsonb)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case p_prize ->> 'kind'
    when 'xp' then coalesce(p_prize ->> 'xp', '0') || ' XP'
    when 'money' then public.format_eur((p_prize ->> 'cents')::bigint)
    when 'skin' then 'das exklusive Accessoire „' || coalesce(p_prize ->> 'name', 'Battle-Skin') || '“'
    when 'accessory' then case when p_prize ? 'name' then 'das Accessoire „' || (p_prize ->> 'name') || '“'
                               else 'ein zufälliges Accessoire (' || case p_prize ->> 'tier' when 'rare' then 'selten'
                                 when 'epic' then 'episch' when 'legendary' then 'legendär' when 'mythic' then 'mythisch'
                                 else 'gewöhnlich' end || ')' end
    when 'packs' then coalesce((select string_agg((x ->> 'count') || ' × ' || coalesce(x ->> 'name', x ->> 'set'), ' + ')
                                  from jsonb_array_elements(p_prize -> 'packs') x), 'Booster') || ' (ungeöffnet)'
    when 'nft' then 'das NFT „' || coalesce(p_prize #>> '{artwork,title}', 'NFT') || '“'
    else 'Ruhm und Ehre' end;
$$;

create or replace function public.battle_pay(p_battle public.battles, p_winner uuid, p_players integer, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.battles_cfg();
  v_prize jsonb := public.battle_prize_json(p_battle, p_players);
  v_money jsonb := jsonb_build_object('kind', 'money', 'cents',
                     (cfg #>> '{prizes,moneyBaseCents}')::bigint + (cfg #>> '{prizes,moneyPerPlayerCents}')::bigint
                       * greatest(p_players, (cfg #>> '{lobby,minPlayers}')::integer), 'fallback', true);
  v_key   text;
  v_name  text;
  v_art   uuid;
  v_xp    integer;
  v_cents bigint;
  v_got   integer := 0;
  a       public.artworks;
  v_e     jsonb;
begin
  if p_winner is null
     or public.battle_prize_wins_today(p_winner, p_now) >= coalesce((cfg #>> '{prizes,dailyPrizeCap}')::integer, 3) then
    return null;
  end if;
  if v_prize ->> 'kind' = 'skin' then
    select x ->> 'key', x ->> 'name' into v_key, v_name
      from jsonb_array_elements(cfg -> 'accessories') x
     where not exists (select 1 from public.player_accessories o where o.player_id = p_winner and o.accessory_key = x ->> 'key')
     order by random() limit 1;
    if v_key is null then
      v_prize := v_money;
    else
      insert into public.player_accessories (player_id, accessory_key, price_paid_cents) values (p_winner, v_key, 0)
      on conflict do nothing;
      return jsonb_build_object('kind', 'skin', 'key', v_key, 'name', v_name);
    end if;
  elsif v_prize ->> 'kind' = 'accessory' then
    -- a random shop accessory of the tier the winner does not own (never a battle exclusive)
    select i ->> 'key', i ->> 'name' into v_key, v_name
      from jsonb_array_elements(coalesce(public.accessories_cfg() -> 'items', '[]'::jsonb)) i
     where i ->> 'rarity' = v_prize ->> 'tier' and not coalesce((i ->> 'exclusive')::boolean, false)
       and not exists (select 1 from public.player_accessories o where o.player_id = p_winner and o.accessory_key = i ->> 'key')
     order by random() limit 1;
    if v_key is null then
      v_prize := v_money;
    else
      insert into public.player_accessories (player_id, accessory_key, price_paid_cents) values (p_winner, v_key, 0)
      on conflict do nothing;
      return jsonb_build_object('kind', 'accessory', 'tier', v_prize ->> 'tier', 'key', v_key, 'name', v_name);
    end if;
  elsif v_prize ->> 'kind' = 'packs' then
    for v_e in select e from jsonb_array_elements(v_prize -> 'packs') e loop
      v_got := v_got + public.nexamon_grant_sealed_packs(p_winner, v_e ->> 'set', (v_e ->> 'count')::integer, 'battle', p_battle.id, 0);
    end loop;
    if v_got > 0 then
      return v_prize;
    end if;
    v_prize := v_money;
  elsif v_prize ->> 'kind' = 'nft' then
    v_art := p_battle.artwork_id;
    if not exists (select 1 from public.artworks x where x.id = v_art and x.owner_id is null and x.ai_owner is null
                     and not exists (select 1 from public.artwork_auctions y where y.artwork_id = x.id and y.status = 'open')) then
      v_art := public.battle_free_artwork(p_battle.artwork_id);
    end if;
    if v_art is null then
      v_prize := v_money;
    else
      update public.artworks set owner_id = p_winner, ask_cents = null, listed_at = null where id = v_art
      returning * into a;
      return jsonb_build_object('kind', 'nft', 'artwork',
        jsonb_build_object('id', a.id, 'title', a.title, 'serial', a.serial, 'rarity', a.rarity, 'pixels', a.pixels));
    end if;
  end if;
  if v_prize ->> 'kind' = 'xp' then
    v_xp := public.grant_xp(p_winner, 'battle'::public.xp_source,
      (cfg #>> '{prizes,xpBase}')::integer + (cfg #>> '{prizes,xpPerPlayer}')::integer
        * greatest(p_players, (cfg #>> '{lobby,minPlayers}')::integer),
      'battle:' || p_battle.id, 'battle', null);
    return jsonb_build_object('kind', 'xp', 'xp', v_xp);
  end if;
  v_cents := (v_prize ->> 'cents')::bigint;
  if v_cents > 0 then
    perform public.ledger_transfer(public.ledger_system_account('households'), public.ledger_player_account(p_winner, 'player_cash'),
                                   v_cents, 'battle_prize'::public.ledger_tx_kind, 'News-Battle gewonnen', 'battle', null,
                                   'battle:' || p_battle.id, p_winner, jsonb_build_object('battle_id', p_battle.id));
  end if;
  return v_prize;
end;
$$;

-- ===== supabase/migrations/20261204006800_news_running_gags.sql =====
-- =============================================================================
-- NEXA · 6800 · Running gags in NEXA Nachrichten (ADR-179)
-- =============================================================================
-- * A running gag (newsShow.runningGags.<key>) comes back show after show while an active player company whose
--   name matches its namePattern (ILIKE) exists: with chanceBps per show, as a segment of kind "gag". First gag:
--   "Vulcan Energy" announces again and again that drilling starts soon, and never does.
-- * news_running_gags counts the aired episodes per gag and company (a new company with the name starts at 1)
--   and remembers the last line, so it never runs twice in a row; lines escalate with the episode.
-- * The made-up chat viewers react around the segment: annoyed lines, and a few die-hard fans with fixed names.
-- * Claude's rewrite (news-anchor) keeps the gag segment as drafted: it must name the player company and founder.
-- * Written idempotently; the copy in supabase/updates/ is identical below its header.
-- =============================================================================

create table if not exists public.news_running_gags (
  gag_key      text not null,
  company_id   uuid not null references public.companies (id) on delete cascade,
  episodes     integer not null default 0 check (episodes >= 0),
  last_line    integer,
  last_show_id bigint,
  first_at     timestamptz,
  last_at      timestamptz,
  primary key (gag_key, company_id)
);
create index if not exists news_running_gags_company_idx on public.news_running_gags (company_id);
alter table public.news_running_gags enable row level security;
comment on table public.news_running_gags is
  'Running gags of NEXA Nachrichten (ADR-179): aired episodes and the last host line per gag and player company. '
  'Server only (no policies).';

-- The company a gag is about right now: the oldest active player company with a matching name.
create or replace function public.news_running_gag_company(p_pattern text)
returns table (company_id uuid, company text, founder text, phase text, founded_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select c.id, c.name, coalesce(p.nickname, '?'), c.phase::text, c.founded_at
    from public.companies c
    left join public.profiles p on p.id = c.founder_id
   where not c.is_ai and c.dissolved_at is null and c.phase in ('private', 'ipo', 'listed')
     and p_pattern is not null and btrim(p_pattern) <> '' and c.name ilike p_pattern
   order by c.founded_at, c.id
   limit 1;
$$;

-- A random element of a json array, or null.
create or replace function public.news_running_gag_pick(p_list jsonb)
returns text
language sql
volatile
set search_path = ''
as $$
  select case when jsonb_typeof(p_list) = 'array' and jsonb_array_length(p_list) > 0
              then p_list ->> floor(random() * jsonb_array_length(p_list))::integer end;
$$;

-- The gag segments of a show (at most one per gag).
create or replace function public.news_show_running_gags(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  gags    jsonb := coalesce(public.news_show_cfg() -> 'runningGags', '{}'::jsonb);
  g       record;
  c       record;
  st      public.news_running_gags;
  v_out   jsonb := '[]'::jsonb;
  v_ep    integer;
  v_total integer;
  v_pool  integer;
  v_line  integer;
  v_i     integer;
  v_vals  jsonb;
  v_text  text;
  v_extra text;
begin
  if jsonb_typeof(gags) <> 'object' then
    return v_out;
  end if;
  for g in select key, value from jsonb_each(gags) where jsonb_typeof(value) = 'object' loop
    continue when not coalesce((g.value ->> 'enabled')::boolean, false);
    select * into c from public.news_running_gag_company(g.value ->> 'namePattern');
    continue when c.company_id is null;
    continue when random() * 10000 >= coalesce((g.value ->> 'chanceBps')::integer, 0);
    v_total := jsonb_array_length(coalesce(g.value -> 'lines', '[]'::jsonb));
    continue when v_total = 0;
    select * into st from public.news_running_gags r where r.gag_key = g.key and r.company_id = c.company_id;
    v_ep := coalesce(st.episodes, 0) + 1;
    -- escalation: episode e may use the first escalateStart + (e - 1) * escalatePerEpisode lines
    v_pool := greatest(1, least(v_total, coalesce((g.value ->> 'escalateStart')::integer, v_total)
                                         + (v_ep - 1) * coalesce((g.value ->> 'escalatePerEpisode')::integer, 0)));
    -- never the line of the last aired episode
    if v_pool <= 1 then
      v_line := 0;
    elsif st.last_line is null or st.last_line < 0 or st.last_line >= v_pool then
      v_line := least(v_pool - 1, floor(random() * v_pool)::integer);
    else
      v_i := least(v_pool - 2, floor(random() * (v_pool - 1))::integer);
      v_line := case when v_i >= st.last_line then v_i + 1 else v_i end;
    end if;
    v_vals := jsonb_build_object(
      'company', c.company, 'founder', c.founder, 'episode', v_ep,
      'days', greatest(1, floor(extract(epoch from (p_now - c.founded_at)) / 86400)::integer + 1),
      'when', coalesce(public.news_running_gag_pick(g.value -> 'whens'), 'bald'));
    v_extra := case when c.phase in ('ipo', 'listed') then public.news_running_gag_pick(g.value #> array['phaseLines', c.phase]) end;
    v_text := public.company_interview_fill(public.news_running_gag_pick(g.value -> 'intros'), v_vals) || ' '
              || public.company_interview_fill(g.value -> 'lines' -> v_line ->> 'text', v_vals)
              || coalesce(' ' || public.company_interview_fill(v_extra, v_vals), '');
    v_out := v_out || jsonb_build_object(
      'kind', 'gag',
      'mood', case when g.value -> 'lines' -> v_line ->> 'mood'
                        in ('neutral', 'shocked', 'crying', 'laughing', 'angry', 'smug', 'confused', 'proud')
                   then g.value -> 'lines' -> v_line ->> 'mood' else 'confused' end,
      'headline', left(public.company_interview_fill(public.news_running_gag_pick(g.value -> 'headlines'), v_vals), 90),
      'text', v_text,
      'effects', '[]'::jsonb,
      'apply', jsonb_build_array(jsonb_build_object('type', 'gag', 'gag', g.key, 'company_id', c.company_id, 'line', v_line)),
      'subject', jsonb_build_object('type', 'gag', 'gag', g.key, 'company_id', c.company_id, 'name', c.company,
                                    'company', c.company, 'values', v_vals),
      'ord', coalesce((g.value ->> 'ord')::integer, 75));
  end loop;
  return v_out;
end;
$$;

-- The made-up viewers around a gag segment: annoyed lines from the usual names, the fans under their own names.
create or replace function public.news_show_gag_chat(p_show_id bigint, p_now timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.news_show_cfg();
  names   jsonb := coalesce(public.news_show_cfg() #> '{chat,bots,names}', '[]'::jsonb);
  s       public.news_shows;
  seg     jsonb;
  gc      jsonb;
  v_idx   bigint;
  v_intro numeric := coalesce((cfg ->> 'introSeconds')::numeric, 8);
  v_seg   numeric := greatest(1, coalesce((cfg ->> 'segmentSeconds')::numeric, 22));
  v_lead  numeric;
  v_span  numeric;
  v_n     integer := 0;
  v_k     integer;
begin
  select * into s from public.news_shows where id = p_show_id;
  if s.id is null then
    return 0;
  end if;
  for seg, v_idx in select x, ord from jsonb_array_elements(s.segments) with ordinality t(x, ord) where x ->> 'kind' = 'gag' loop
    gc := cfg #> array['runningGags', seg -> 'subject' ->> 'gag', 'chat'];
    continue when gc is null;
    v_lead := coalesce((gc ->> 'leadSeconds')::numeric, 0);
    v_span := v_lead + v_seg + coalesce((gc ->> 'tailSeconds')::numeric, 0);
    -- annoyed viewers (no line twice in a segment)
    if jsonb_array_length(names) > 0 then
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      select null, names ->> floor(random() * jsonb_array_length(names))::integer,
             left(public.company_interview_fill(l, seg -> 'subject' -> 'values'), 300),
             p_now + make_interval(secs => (v_intro + (v_idx - 1) * v_seg - v_lead + random() * v_span)::double precision)
        from (select l from jsonb_array_elements_text(coalesce(gc -> 'annoyed', '[]'::jsonb)) l
               order by random() limit greatest(0, coalesce((gc ->> 'annoyedPerSegment')::integer, 0))) a;
      get diagnostics v_k = row_count;
      v_n := v_n + v_k;
    end if;
    -- the die-hard fans
    if jsonb_array_length(coalesce(gc -> 'fanNames', '[]'::jsonb)) > 0 then
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      select null, public.news_running_gag_pick(gc -> 'fanNames'),
             left(public.company_interview_fill(l, seg -> 'subject' -> 'values'), 300),
             p_now + make_interval(secs => (v_intro + (v_idx - 1) * v_seg - v_lead + random() * v_span)::double precision)
        from (select l from jsonb_array_elements_text(coalesce(gc -> 'fans', '[]'::jsonb)) l
               order by random() limit greatest(0, coalesce((gc ->> 'fansPerSegment')::integer, 0))) f;
      get diagnostics v_k = row_count;
      v_n := v_n + v_k;
    end if;
  end loop;
  return v_n;
end;
$$;

-- news_show_build(): the gag joins the show
do $do$
declare
  v_def text := pg_get_functiondef('public.news_show_build(timestamptz)'::regprocedure);
  v_old text := $t$  v_segs := v_segs || public.news_show_interviews(p_now);$t$;
begin
  if position('news_show_running_gags' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'news_show_build() has an unexpected shape; add the call of news_show_running_gags() (ADR-179) by hand';
    end if;
    execute replace(v_def, v_old, $t$  -- 12. running gags (ADR-179): back every show while their player company exists
  v_segs := v_segs || public.news_show_running_gags(p_now);
$t$ || v_old);
  end if;
end;
$do$;

-- news_show_start(): an aired gag counts as an episode (once per show); the feed files it under companies
do $do$
declare
  v_def  text := pg_get_functiondef('public.news_show_start(bigint, timestamptz)'::regprocedure);
  v_when text := $t$        when 'tasks' then$t$;
  v_kind text := $t$'corp', 'interview') then 'company'$t$;
begin
  if position('news_running_gags' in v_def) = 0 then
    if position(v_when in v_def) = 0 or position(v_kind in v_def) = 0 then
      raise exception 'news_show_start() has an unexpected shape; add the apply type "gag" (ADR-179) by hand';
    end if;
    v_def := replace(v_def, v_when, $t$        when 'gag' then
          if exists (select 1 from public.companies c where c.id = (a ->> 'company_id')::uuid) then
            insert into public.news_running_gags as rg (gag_key, company_id, episodes, last_line, last_show_id, first_at, last_at)
            values (a ->> 'gag', (a ->> 'company_id')::uuid, 1, (a ->> 'line')::integer, s.id, p_now, p_now)
            on conflict (gag_key, company_id) do update
              set episodes = rg.episodes + 1, last_line = excluded.last_line, last_show_id = excluded.last_show_id,
                  last_at = excluded.last_at
              where rg.last_show_id is distinct from excluded.last_show_id;
          end if;
$t$ || v_when);
    v_def := replace(v_def, v_kind, $t$'corp', 'interview', 'gag') then 'company'$t$);
    execute v_def;
  end if;
end;
$do$;

-- news_show_after_start(): the viewers react to the gag
do $do$
declare
  v_def text := pg_get_functiondef('public.news_show_after_start(bigint, timestamptz)'::regprocedure);
  v_old text := $t$  return v_n;
end;$t$;
begin
  if position('news_show_gag_chat' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'news_show_after_start() has an unexpected shape; add the call of news_show_gag_chat() (ADR-179) by hand';
    end if;
    execute replace(v_def, v_old, $t$  -- running gags (ADR-179): annoyed viewers and die-hard fans around the segment
  v_n := v_n + public.news_show_gag_chat(p_show_id, p_now);
$t$ || v_old);
  end if;
end;
$do$;

-- store_news_show_script(): Claude's rewrite keeps gag segments as drafted (they name the player company)
do $do$
declare
  v_def text := pg_get_functiondef('public.store_news_show_script(bigint, jsonb)'::regprocedure);
  v_old text := $t$  update public.news_shows set segments = v_new, writer = 'claude' where id = s.id;$t$;
begin
  if position('''gag''' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'store_news_show_script() has an unexpected shape; keep gag segments (ADR-179) by hand';
    end if;
    execute replace(v_def, v_old, $t$  -- running gags (ADR-179) stay as drafted
  select jsonb_agg(case when o.x ->> 'kind' = 'gag' then o.x else n.x end order by o.ord) into v_new
    from jsonb_array_elements(s.segments) with ordinality o(x, ord)
    join jsonb_array_elements(v_new) with ordinality n(x, ord) using (ord);
$t$ || v_old);
  end if;
end;
$do$;

revoke all on function public.news_running_gag_company(text) from public, anon, authenticated;
revoke all on function public.news_running_gag_pick(jsonb) from public, anon, authenticated;
revoke all on function public.news_show_running_gags(timestamptz) from public, anon, authenticated;
revoke all on function public.news_show_gag_chat(bigint, timestamptz) from public, anon, authenticated;

-- ===== supabase/migrations/20261204006850_news_used_keys_distinct.sql =====
-- news_show_after_start(): mark every subject key of the show as used once. The old statement selected
-- `distinct ukey, clock_timestamp()`, and clock_timestamp() differs per row, so two segments with the same subject
-- key reached ON CONFLICT twice in one command ("cannot affect row a second time"). Idempotent replace-patch.
do $do$
declare
  v_def text := pg_get_functiondef('public.news_show_after_start(bigint, timestamptz)'::regprocedure);
  v_old text := $t$select distinct x -> 'subject' ->> 'ukey', clock_timestamp()
    from jsonb_array_elements(s.segments) x where x -> 'subject' ->> 'ukey' is not null$t$;
  v_new text := $t$select k.ukey, clock_timestamp()
    from (select distinct x -> 'subject' ->> 'ukey' as ukey
            from jsonb_array_elements(s.segments) x where x -> 'subject' ->> 'ukey' is not null) k$t$;
begin
  if position(v_new in v_def) > 0 then
    return;
  end if;
  if position(v_old in v_def) = 0 then
    raise exception 'news_show_after_start() has an unexpected shape; dedupe the used subject keys by hand';
  end if;
  execute replace(v_def, v_old, v_new);
end;
$do$;

-- ===== supabase/migrations/20261204006900_company_economy.sql =====
-- =============================================================================
-- NEXA · 6900 · Company economy overhaul (ADR-180): awareness every hour, AI workers paid for used capacity
-- =============================================================================
-- * company_awareness_hour(): port of awarenessHour (src/lib/sim/startup.ts). Word of mouth, the hour's marketing
--   and decay move the awareness after every closed hour (before: once per quarter, invisible for six hours).
-- * company_ai_utilization_bps() / company_ai_wage_due_cents(): ports of aiUtilizationBps / aiWageDueCents. AI workers
--   serve what founder and players cannot; the full wage only for the used part, at least aiWorkerStandbyBps.
-- * player_company_close_hour (patched by replace): AI wages by utilization, the awareness step, and the parts in the
--   hour row (ai_utilization_bps, awareness_before, awareness_after, awareness_parts) so the page can say
--   "+0,8 Bekanntheit diese Stunde durch Marketing".
-- * player_company_close_quarter (patched by replace): the quarter no longer moves awareness, it only reports it.
-- * company_strengths_instant (patched by replace): awareness counts against companyHealth.strengths.awarenessFull.
-- * company_awareness_boost(): levers outside the hour (tasks, autopilot) add awareness at once and remember it in
--   player_companies.awareness_boost, which the next hour reports as its "extra" part.
-- The new numbers (market x 10, capacity x 1.5, marketing and decay) come with game_config (pnpm db:config).
-- Idempotent: runs unchanged as supabase/updates/20261204006900_company_economy.sql.

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_company_hours add column if not exists ai_utilization_bps integer;
alter table public.player_company_hours add column if not exists awareness_before double precision;
alter table public.player_company_hours add column if not exists awareness_after double precision;
alter table public.player_company_hours add column if not exists awareness_parts jsonb;
comment on column public.player_company_hours.ai_utilization_bps is
  'Share of the AI workers'' capacity the hour used, 0..10 000 (ADR-180); below the standby share they cost that.';
comment on column public.player_company_hours.awareness_parts is
  'What moved the awareness this hour (ADR-180): word_of_mouth, marketing, decay, extra (tasks, autopilot), shares.';
alter table public.player_companies add column if not exists awareness_boost double precision not null default 0;
comment on column public.player_companies.awareness_boost is
  'Awareness added since the last closed hour by tasks and the autopilot (ADR-180); the hour reports and resets it.';

-- ---------------------------------------------------------------------------
-- B. Rules (ports of src/lib/sim/startup.ts)
-- ---------------------------------------------------------------------------
create or replace function public.company_awareness_hour(p_awareness double precision, p_quality double precision,
  p_marketing_cents double precision, p_potential double precision, p_price_awareness double precision, p_stage integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_su    jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_a     double precision := coalesce(p_awareness, 0);
  v_caps  jsonb := coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb);
  v_stage integer := least(greatest(coalesce(p_stage, 0), 0), greatest(jsonb_array_length(v_caps) - 1, 0));
  v_min   double precision := public.cfg_num(v_su, '{awareness,min}', 0.01);
  v_cap   double precision;
  v_wom   double precision;
  v_mk    double precision := 0;
  v_mkq   double precision := greatest(0, coalesce(p_marketing_cents, 0)) * v_hours;
  v_half  double precision;
  v_decay double precision;
begin
  v_cap := greatest(v_min, coalesce((v_caps ->> v_stage)::double precision, 1));
  v_wom := public.cfg_num(v_su, '{awareness,growthPerQuarter}', 0.2) / v_hours * coalesce(p_price_awareness, 1)
           * v_a * (1 - v_a) * (0.5 + coalesce(p_quality, 0));
  if v_mkq > 0 then
    v_half := greatest(public.cfg_num(v_su, '{awareness,marketingMinHalfSaturationCents}', 50000),
                       coalesce(p_potential, 0) / 4.0 * public.cfg_num(v_su, '{awareness,marketingHalfSaturationShare}', 0.01));
    v_mk := public.cfg_num(v_su, '{awareness,marketingMaxGain}', 0.24) * v_mkq / (v_mkq + v_half) / v_hours;
  end if;
  v_decay := public.cfg_num(v_su, '{awareness,decayPerQuarter}', 0.12) / v_hours * v_a;
  return jsonb_build_object('before', v_a, 'next', least(v_cap, greatest(v_min, v_a + v_wom + v_mk - v_decay)),
                            'word_of_mouth', v_wom, 'marketing', v_mk, 'decay', v_decay, 'cap', v_cap);
end;
$$;

create or replace function public.company_ai_utilization_bps(p_sold double precision, p_capacity double precision,
  p_ai_workers integer, p_units double precision)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_ai_workers, 0) <= 0 or coalesce(p_units, 0) <= 0 or coalesce(p_capacity, 0) <= 0 then 0
              else floor(least(1.0, greatest(0.0,
                     (p_sold - (p_capacity - p_capacity * least(p_ai_workers::double precision, p_units) / p_units))
                     / (p_capacity * least(p_ai_workers::double precision, p_units) / p_units))) * 10000)::integer end;
$$;

create or replace function public.company_ai_wage_due_cents(p_ai_workers integer, p_utilization_bps integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select case when coalesce(p_ai_workers, 0) <= 0 then 0::bigint
              else (p_ai_workers::bigint * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000)
                    * greatest(public.config_bigint('startups', '{aiWorkerStandbyBps}', 2500),
                               least(10000, coalesce(p_utilization_bps, 0)))::bigint) / 10000 end;
$$;

-- Levers outside the hour (ADR-180): add awareness at once (never above the stage's cap), remembered for the hour.
create or replace function public.company_awareness_boost(p_company uuid, p_add double precision)
returns double precision
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc     public.player_companies;
  v_su   jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_caps jsonb := coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb);
  v_cap  double precision;
  v_new  double precision;
begin
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null or coalesce(p_add, 0) = 0 then
    return 0;
  end if;
  v_cap := coalesce((v_caps ->> least(greatest(coalesce((public.player_company_team(p_company) ->> 'stage')::integer, 0), 0),
                                        greatest(jsonb_array_length(v_caps) - 1, 0)))::double precision, 1);
  if p_add > 0 then
    v_new := least(greatest(v_cap, pc.awareness), pc.awareness + p_add);
  else
    v_new := greatest(public.cfg_num(v_su, '{awareness,min}', 0.01), pc.awareness + p_add);
  end if;
  update public.player_companies
     set awareness = v_new, awareness_boost = awareness_boost + (v_new - pc.awareness)
   where company_id = p_company;
  return v_new - pc.awareness;
end;
$$;
revoke all on function public.company_awareness_boost(uuid, double precision) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- C. The hourly close (patched by replace; clear error when an anchor is missing)
-- ---------------------------------------------------------------------------
do $patch$
declare
  v_def text := pg_get_functiondef('public.player_company_close_hour(uuid, timestamptz)'::regprocedure);
  a1 text := $a$  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);$a$;
  b1 text := $b$  -- ADR-180: AI workers fill what founder and players cannot; the full wage only for the used capacity
  v_aiutil := public.company_ai_utilization_bps(v_sold, v_cap, pc.ai_workers,
                (v_team ->> 'team_productivity_bps')::double precision / 10000.0);
  v_aidue := public.company_ai_wage_due_cents(pc.ai_workers, v_aiutil);$b$;
  a2 text := $a$  update public.player_company_hours set strength_bonus_cents = v_sbonus where company_id = p_company and hour_start = v_start;$a$;
  b2 text := $b$  update public.player_company_hours set strength_bonus_cents = v_sbonus where company_id = p_company and hour_start = v_start;
  -- ADR-180: awareness moves every hour (word of mouth, the hour's marketing, decay); boosts since the last hour
  -- (tasks, autopilot) are reported as "extra"
  select x.awareness, x.quality, x.awareness_boost into v_aw0, v_q0, v_boost
    from public.player_companies x where x.company_id = p_company;
  v_awh := public.company_awareness_hour(v_aw0, v_q0, v_mk::double precision,
             pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level),
             (public.company_price_effect(pc.price_level, v_q0) ->> 'awareness')::double precision, v_stage);
  update public.player_companies set awareness = (v_awh ->> 'next')::double precision, awareness_boost = 0
   where company_id = p_company;
  update public.player_company_hours
     set ai_utilization_bps = v_aiutil, awareness_before = v_aw0 - coalesce(v_boost, 0),
         awareness_after = (v_awh ->> 'next')::double precision,
         awareness_parts = jsonb_build_object('word_of_mouth', v_awh -> 'word_of_mouth', 'marketing', v_awh -> 'marketing',
                                              'decay', v_awh -> 'decay', 'extra', coalesce(v_boost, 0), 'cap', v_awh -> 'cap')
   where company_id = p_company and hour_start = v_start;$b$;
  a3 text := $a$  v_sbonus  bigint := 0;  -- ADR-176 (company_strengths)$a$;
  b3 text := $b$  v_sbonus  bigint := 0;  -- ADR-176 (company_strengths)
  v_aiutil  integer := 0;  -- ADR-180
  v_awh     jsonb;
  v_aw0     double precision;
  v_q0      double precision;
  v_boost   double precision;$b$;
begin
  if position('ADR-180' in v_def) > 0 then
    return;
  end if;
  if position(a1 in v_def) = 0 then raise exception 'NEXA 6900: close_hour anchor (AI wages) missing'; end if;
  if position(a2 in v_def) = 0 then raise exception 'NEXA 6900: close_hour anchor (strength bonus) missing'; end if;
  if position(a3 in v_def) = 0 then raise exception 'NEXA 6900: close_hour anchor (declare) missing'; end if;
  v_def := replace(replace(replace(v_def, a1, b1), a2, b2), a3, b3);
  execute v_def;
end;
$patch$;

-- the quarter reports the awareness, it no longer moves it
do $patch$
declare
  v_def text := pg_get_functiondef('public.player_company_close_quarter(uuid, bigint)'::regprocedure);
  a1 text := $a$  -- profit bonus (ADR-058)$a$;
begin
  if position('ADR-180' in v_def) > 0 then
    return;
  end if;
  if position(a1 in v_def) = 0 then raise exception 'NEXA 6900: close_quarter anchor (profit bonus) missing'; end if;
  v_def := replace(v_def, a1, '  v_aw := pc.awareness;  -- ADR-180: awareness moves every hour, the quarter only reports it' || chr(10) || a1);
  execute v_def;
end;
$patch$;

-- strengths: awareness against awarenessFull (ADR-180)
do $patch$
declare
  v_def text := pg_get_functiondef('public.company_strengths_instant(double precision, double precision, double precision, double precision, bigint, bigint, integer, bigint, bigint)'::regprocedure);
  a1 text := $a$'awareness', least(100.0, greatest(0.0, 100 * coalesce(p_awareness, 0))),$a$;
  b1 text := $b$'awareness', least(100.0, greatest(0.0, 100 * coalesce(p_awareness, 0)
                                    / greatest(0.01, public.cfg_num(cfg, '{awarenessFull}', 1)))),  -- ADR-180$b$;
begin
  if position('ADR-180' in v_def) > 0 then
    return;
  end if;
  if position(a1 in v_def) = 0 then raise exception 'NEXA 6900: strengths_instant anchor missing'; end if;
  execute replace(v_def, a1, b1);
end;
$patch$;

revoke all on function public.company_awareness_hour(double precision, double precision, double precision, double precision,
  double precision, integer) from public, anon, authenticated;
revoke all on function public.company_ai_utilization_bps(double precision, double precision, integer, double precision)
  from public, anon, authenticated;
revoke all on function public.company_ai_wage_due_cents(integer, integer) from public, anon, authenticated;

-- ===== supabase/migrations/20261204006910_company_autopilot.sql =====
-- =============================================================================
-- NEXA · 6910 · Company autopilot and task pay with the strengths (ADR-180)
-- =============================================================================
-- * company_autopilot: per company on/off (founder). While on, company_autopilot_run() (called by the minutely
--   company_tasks_run_due) takes every open task that waited companyTasks.autopilot.delayMinutes and resolves it
--   without a mini-game: chance = base + (max - base) x mood (src/lib/sim/company-autopilot.ts), mood = employee
--   satisfaction (listed) or the "Team" strength (private). Success pays rewardBps of a perfect run x the chance above
--   100 %; failure costs failPenaltyBps. Without anyone active it creates a task every everyMinutes itself, at most
--   maxPerDay autopilot tasks per Berlin day. company_autopilot_log keeps every result; from summaryHour the founder
--   gets one notification with the night's summary.
-- * company_task_resolve (patched by replace): the autopilot share, the strengths pay factor on every success
--   (company_task_pay_factor_bps, 0.9x..1.5x) and awareness for every solved task (company_awareness_boost).
-- * get_company_autopilot() / set_company_autopilot(): state, today's numbers, the log and the last hour's economy.
-- Idempotent: runs unchanged as supabase/updates/20261204006910_company_autopilot.sql.

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.company_tasks add column if not exists autopilot_chance_bps integer;
comment on column public.company_tasks.autopilot_chance_bps is
  'Set when the autopilot resolved the task (ADR-180): the chance it had, in bps (up to 12 000).';

create table if not exists public.company_autopilot (
  company_id      uuid primary key references public.player_companies (company_id) on delete cascade,
  enabled         boolean not null default false,
  enabled_at      timestamptz,
  summary_sent_on date,
  updated_at      timestamptz not null default now()
);
alter table public.company_autopilot enable row level security;
drop trigger if exists set_updated_at on public.company_autopilot;
create trigger set_updated_at before update on public.company_autopilot
  for each row execute function public.set_updated_at();
revoke all on public.company_autopilot from anon, authenticated;
comment on table public.company_autopilot is
  'Autopilot per player company (ADR-180). Read and written through get_company_autopilot / set_company_autopilot.';

create table if not exists public.company_autopilot_log (
  id           bigint generated always as identity primary key,
  company_id   uuid not null references public.player_companies (company_id) on delete cascade,
  task_id      bigint,
  task_key     text not null,
  success      boolean not null,
  result_cents bigint not null,
  chance_bps   integer not null check (chance_bps >= 0),
  at           timestamptz not null default now()
);
create index if not exists company_autopilot_log_company_at on public.company_autopilot_log (company_id, at desc);
alter table public.company_autopilot_log enable row level security;
revoke all on public.company_autopilot_log from anon, authenticated;
comment on table public.company_autopilot_log is
  'Every task the autopilot resolved (ADR-180); kept 7 days. Read through get_company_autopilot.';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('company_autopilot', 'company', 'Autopilot', 'Morgens: was der Autopilot deiner Firma über Nacht erledigt hat.',
        'notif_company', true, true, false, 211)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Rules (ports of src/lib/sim/company-autopilot.ts)
-- ---------------------------------------------------------------------------
create or replace function public.company_strengths_overall_of(p_company uuid)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select public.company_strengths_overall(s.scores) from public.company_strengths s
                    where s.company_id = p_company), 0);
$$;

-- task pay factor from the strengths: minBps at overall 0 .. maxBps at 100 (taskPayFactorBps)
create or replace function public.company_task_pay_factor_bps(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select floor(public.cfg_num(public.company_tasks_cfg(), '{strengthPay,minBps}', 9000)
               + (public.cfg_num(public.company_tasks_cfg(), '{strengthPay,maxBps}', 15000)
                  - public.cfg_num(public.company_tasks_cfg(), '{strengthPay,minBps}', 9000))
                 * least(100, greatest(0, public.company_strengths_overall_of(p_company))) / 100)::integer;
$$;

-- mood 0..1 (autopilotMood): satisfaction of a listed company, else the "Team" strength
create or replace function public.company_autopilot_mood(p_company uuid)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select least(1.0, greatest(0.0, coalesce(
    (select l.satisfaction from public.listed_companies l where l.company_id = p_company),
    (select (s.scores ->> 'team')::double precision from public.company_strengths s where s.company_id = p_company),
    0) / 100.0));
$$;

-- chance in bps (autopilotChanceBps)
create or replace function public.company_autopilot_chance_bps(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select floor(public.cfg_num(public.company_tasks_cfg(), '{autopilot,baseChanceBps}', 6000)
               + (public.cfg_num(public.company_tasks_cfg(), '{autopilot,maxChanceBps}', 12000)
                  - public.cfg_num(public.company_tasks_cfg(), '{autopilot,baseChanceBps}', 6000))
                 * public.company_autopilot_mood(p_company))::integer;
$$;

-- ---------------------------------------------------------------------------
-- C. Resolving a task (patched by replace)
-- ---------------------------------------------------------------------------
do $patch$
declare
  v_def text := pg_get_functiondef('public.company_task_resolve(bigint, integer, boolean)'::regprocedure);
  a1 text := $a$    if p_by_ai then
      v_amount := (v_amount * (cfg -> 'ai' ->> 'valueBps')::integer) / 10000;
    end if;$a$;
  b1 text := $b$    if t.autopilot_chance_bps is not null then
      -- ADR-180 autopilot: its share of a perfect run, the chance above 100 % as a bonus
      v_amount := (v_amount * (cfg -> 'autopilot' ->> 'rewardBps')::integer) / 10000;
      v_amount := (v_amount * greatest(10000, t.autopilot_chance_bps)) / 10000;
    elsif p_by_ai then
      v_amount := (v_amount * (cfg -> 'ai' ->> 'valueBps')::integer) / 10000;
    end if;
    -- ADR-180: strong companies earn more per task (0.9x .. 1.5x by the six strengths)
    v_amount := (v_amount * public.company_task_pay_factor_bps(t.company_id)) / 10000;$b$;
  a2 text := $a$    v_amount := (t.value_cents * (cfg ->> 'penaltyBps')::integer) / 10000;$a$;
  b2 text := $b$    v_amount := (t.value_cents * case when t.autopilot_chance_bps is not null
                                      then (cfg -> 'autopilot' ->> 'failPenaltyBps')::integer
                                      else (cfg ->> 'penaltyBps')::integer end) / 10000;  -- ADR-180$b$;
  a3 text := $a$  perform public.company_task_momentum_apply(t.company_id, p_score, p_by_ai);$a$;
  b3 text := $b$  perform public.company_task_momentum_apply(t.company_id, p_score, p_by_ai);
  -- ADR-180: a solved task makes the company a little better known at once (AI and autopilot half)
  if v_ok then
    perform public.company_awareness_boost(t.company_id,
      public.config_double('startups', '{awareness,taskGain}', 0.002)
      * case when p_by_ai then public.config_double('startups', '{awareness,taskAiShareBps}', 5000) / 10000.0 else 1 end);
  end if;$b$;
begin
  if position('ADR-180' in v_def) > 0 then
    return;
  end if;
  if position(a1 in v_def) = 0 then raise exception 'NEXA 6910: task_resolve anchor (AI share) missing'; end if;
  if position(a2 in v_def) = 0 then raise exception 'NEXA 6910: task_resolve anchor (penalty) missing'; end if;
  if position(a3 in v_def) = 0 then raise exception 'NEXA 6910: task_resolve anchor (momentum) missing'; end if;
  execute replace(replace(replace(v_def, a1, b1), a2, b2), a3, b3);
end;
$patch$;

-- ---------------------------------------------------------------------------
-- D. The autopilot run (every minute from company_tasks_run_due)
-- ---------------------------------------------------------------------------
create or replace function public.company_autopilot_run(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.company_tasks_cfg();
  ap       jsonb := public.company_tasks_cfg() -> 'autopilot';
  v_now    timestamptz := coalesce(p_now, public.game_now());
  v_day0   timestamptz := date_trunc('day', coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin') at time zone 'Europe/Berlin';
  r        record;
  t        record;
  v_def    jsonb;
  v_today  integer;
  v_left   integer;
  v_chance integer;
  v_ok     boolean;
  v_res    jsonb;
  v_done   integer := 0;
  v_new    integer := 0;
  v_sent   integer := 0;
  s        record;
begin
  if ap is null then
    return jsonb_build_object('skipped', 'no config');
  end if;
  for r in select a.company_id, a.enabled_at, a.summary_sent_on, pc.founder_id, pc.tier, pc.product_key, pc.tasks_last_created_at,
                  c.name
             from public.company_autopilot a
             join public.player_companies pc on pc.company_id = a.company_id and pc.status = 'active'
             join public.companies c on c.id = a.company_id
            where a.enabled
            order by a.company_id
  loop
    select count(*) into v_today from public.company_autopilot_log l where l.company_id = r.company_id and l.at >= v_day0;
    v_left := (ap ->> 'maxPerDay')::integer - v_today;
    -- nobody around: the autopilot brings its own work, slowly
    if v_left > 0
       and (r.tasks_last_created_at is null or r.tasks_last_created_at <= v_now - make_interval(mins => (ap ->> 'everyMinutes')::integer))
       and not exists (select 1 from public.company_tasks x where x.company_id = r.company_id and x.status in ('open', 'assigned', 'playing', 'ai'))
    then
      select x into v_def from jsonb_array_elements(cfg -> 'tasks') x
       where x ->> 'product' = '*' or x ->> 'product' = r.product_key
       order by random() limit 1;
      if v_def is not null then
        insert into public.company_tasks (company_id, task_key, branch, game, value_cents, created_at, due_at)
        values (r.company_id, v_def ->> 'key', v_def ->> 'branch', v_def ->> 'game',
                greatest(1, round((cfg -> 'valueCentsByTier' ->> r.tier::text)::numeric * (v_def ->> 'factor')::numeric)::bigint),
                v_now - make_interval(mins => (ap ->> 'delayMinutes')::integer),
                v_now + make_interval(mins => (v_def ->> 'minutes')::integer));
        update public.player_companies set tasks_last_created_at = v_now where company_id = r.company_id;
        v_new := v_new + 1;
      end if;
    end if;
    -- every open task that waited long enough (people get the first minutes)
    for t in select x.id, x.task_key from public.company_tasks x
              where x.company_id = r.company_id and x.status = 'open' and x.due_at > v_now
                and x.created_at <= v_now - make_interval(mins => (ap ->> 'delayMinutes')::integer)
              order by x.created_at, x.id
              limit greatest(0, v_left)
              for update skip locked
    loop
      v_chance := public.company_autopilot_chance_bps(r.company_id);
      v_ok := v_chance >= 10000 or random() * 10000 < v_chance;
      update public.company_tasks
         set autopilot_chance_bps = v_chance, assignee_ai = true, assignee_id = null, done_by = null
       where id = t.id;
      v_res := public.company_task_resolve(t.id, case when v_ok then 10000 else 0 end, true);
      insert into public.company_autopilot_log (company_id, task_id, task_key, success, result_cents, chance_bps, at)
      values (r.company_id, t.id, t.task_key, v_ok, coalesce((v_res ->> 'result_cents')::bigint, 0), v_chance, v_now);
      v_done := v_done + 1;
    end loop;
    -- the morning summary: once per Berlin day from summaryHour, about everything since the last one
    if extract(hour from v_now at time zone 'Europe/Berlin') >= (ap ->> 'summaryHour')::integer
       and (r.summary_sent_on is null or r.summary_sent_on < (v_now at time zone 'Europe/Berlin')::date) then
      select count(*) as n, count(*) filter (where l.success) as ok, coalesce(sum(l.result_cents), 0) as cents into s
        from public.company_autopilot_log l
       where l.company_id = r.company_id
         and l.at > greatest(coalesce(r.enabled_at, v_now - interval '1 day'), v_day0 - interval '1 day'
                               + make_interval(hours => (ap ->> 'summaryHour')::integer));
      if s.n > 0 then
        perform public.social_notify(r.founder_id, 'company_autopilot', 'Autopilot: ' || s.n || ' Aufgaben erledigt',
          r.name || ': ' || s.ok || ' erfolgreich, ' || (s.n - s.ok) || ' daneben, '
            || case when s.cents >= 0 then '+' else '−' end
            || to_char(abs(s.cents) / 100.0, 'FM999G999G990D00') || ' €.',
          jsonb_build_object('done', s.n, 'success', s.ok, 'cents', s.cents), '/company',
          'autopilot:' || r.company_id::text || ':' || to_char(v_now at time zone 'Europe/Berlin', 'YYYY-MM-DD'));
        v_sent := v_sent + 1;
      end if;
      update public.company_autopilot set summary_sent_on = (v_now at time zone 'Europe/Berlin')::date
       where company_id = r.company_id;
    end if;
  end loop;
  delete from public.company_autopilot_log where at < v_now - interval '7 days';
  return jsonb_build_object('done', v_done, 'new', v_new, 'summaries', v_sent);
end;
$$;
revoke all on function public.company_autopilot_run(timestamptz) from public, anon, authenticated;

do $patch$
declare
  v_def text := pg_get_functiondef('public.company_tasks_run_due(timestamptz)'::regprocedure);
  a1 text := $a$  delete from public.company_tasks where resolved_at < v_now - interval '3 days';$a$;
begin
  if position('company_autopilot_run' in v_def) > 0 then
    return;
  end if;
  if position(a1 in v_def) = 0 then raise exception 'NEXA 6910: tasks_run_due anchor (cleanup) missing'; end if;
  execute replace(v_def, a1, '  perform public.company_autopilot_run(v_now);  -- ADR-180' || chr(10) || a1);
end;
$patch$;

-- ---------------------------------------------------------------------------
-- E. API
-- ---------------------------------------------------------------------------
create or replace function public.company_autopilot_json(p_company uuid, p_player uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  ap      jsonb := public.company_tasks_cfg() -> 'autopilot';
  v_now   timestamptz := public.game_now();
  v_day0  timestamptz := date_trunc('day', public.game_now() at time zone 'Europe/Berlin') at time zone 'Europe/Berlin';
  a       public.company_autopilot;
  pc      public.player_companies;
  h       public.player_company_hours;
  v_today jsonb;
  v_log   jsonb;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into a from public.company_autopilot where company_id = p_company;
  select jsonb_build_object('done', count(*), 'success', count(*) filter (where l.success),
                            'cents', coalesce(sum(l.result_cents), 0))
    into v_today from public.company_autopilot_log l where l.company_id = p_company and l.at >= v_day0;
  select coalesce(jsonb_agg(jsonb_build_object('at', x.at, 'key', x.task_key, 'success', x.success,
                                               'result_cents', x.result_cents, 'chance_bps', x.chance_bps) order by x.at desc, x.id desc), '[]'::jsonb)
    into v_log
    from (select * from public.company_autopilot_log l where l.company_id = p_company
           order by l.at desc, l.id desc limit coalesce((ap ->> 'logLimit')::integer, 15)) x;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  return jsonb_build_object(
    'on', coalesce(a.enabled, false),
    'can_toggle', pc.founder_id = p_player,
    'mood', public.company_autopilot_mood(p_company),
    'chance_bps', public.company_autopilot_chance_bps(p_company),
    'reward_bps', (ap ->> 'rewardBps')::integer,
    'fail_penalty_bps', (ap ->> 'failPenaltyBps')::integer,
    'max_per_day', (ap ->> 'maxPerDay')::integer,
    'every_minutes', (ap ->> 'everyMinutes')::integer,
    'pay_factor_bps', public.company_task_pay_factor_bps(p_company),
    'today', v_today,
    'log', v_log,
    'last_hour', case when h.company_id is null then null else jsonb_build_object(
      'hour_start', h.hour_start, 'revenue_cents', h.revenue_cents, 'profit_cents', h.profit_cents,
      'demand_cents', h.demand_cents, 'capacity_cents', h.capacity_cents,
      'ai_workers', pc.ai_workers, 'ai_wages_due_cents', h.ai_wages_due_cents,
      'ai_utilization_bps', h.ai_utilization_bps,
      'awareness_before', h.awareness_before, 'awareness_after', h.awareness_after,
      'awareness_parts', h.awareness_parts) end);
end;
$$;

create or replace function public.get_company_autopilot()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  m        record;
begin
  select * into m from public.company_task_member(v_player);
  if m.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  return public.company_autopilot_json(m.company_id, v_player);
end;
$$;

create or replace function public.set_company_autopilot(p_request_id uuid, p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_replay jsonb;
  pc       public.player_companies;
begin
  if p_request_id is null or p_on is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_autopilot');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where founder_id = v_player and status = 'active';
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  insert into public.company_autopilot as a (company_id, enabled, enabled_at, updated_at)
  values (pc.company_id, p_on, case when p_on then public.game_now() end, now())
  on conflict (company_id) do update
    set enabled = excluded.enabled,
        enabled_at = case when excluded.enabled and not a.enabled then excluded.enabled_at else a.enabled_at end,
        updated_at = now();
  return public.request_complete(v_player, p_request_id, public.company_autopilot_json(pc.company_id, v_player));
end;
$$;

revoke all on function public.company_autopilot_json(uuid, uuid) from public, anon, authenticated;
revoke all on function public.get_company_autopilot() from public, anon;
revoke all on function public.set_company_autopilot(uuid, boolean) from public, anon;
grant execute on function public.get_company_autopilot() to authenticated;
grant execute on function public.set_company_autopilot(uuid, boolean) to authenticated;

